	 */
	if (chunk)
		retval->transport = chunk->transport;

nodata:
	return retval;
}

static inline int /* <=== sctp_chunk_length_valid */ 
sctp_chunk_length_valid(struct sctp_chunk *chunk,
			   __u16 required_length)
{
