static inline ktime_t ktime_sub(const ktime_t lhs, const ktime_t rhs) /* <=== ktime_sub */ 
{
	ktime_t res;

	res.tv64 = lhs.tv64 - rhs.tv64;
	if (res.tv.nsec < 0)
		res.tv.nsec += NSEC_PER_SEC;

	return res;
}

